const reportStaffShares = `-- name: ReportStaffShares :many
SELECT l.share_date, l.branch_id, l.currency::text AS currency,
    COALESCE(SUM(l.share_amount), 0)::numeric AS share
FROM staff_share_lines l
WHERE l.organization_id = $1
  AND l.share_date BETWEEN $2::date AND $3::date
  AND ($4::bigint[] IS NULL OR l.branch_id = ANY($4::bigint[]))
  AND ($5::bigint[] IS NULL OR l.branch_id = ANY($5::bigint[]))
  AND ($6::bigint[] IS NULL OR l.staff_id = ANY($6::bigint[]))
GROUP BY l.share_date, l.branch_id, l.currency
ORDER BY l.share_date, l.branch_id, l.currency
`

