const reportStockLevels = `-- name: ReportStockLevels :many
SELECT st.branch_id,
    COALESCE(SUM(st.on_hand), 0)::bigint AS on_hand,
    COALESCE(SUM(st.reserved), 0)::bigint AS reserved,
    COALESCE(SUM(st.on_hand * COALESCE(v.cost, p.cost)), 0)::numeric AS stock_value,
    COUNT(*) FILTER (WHERE st.on_hand - st.reserved > 0 AND st.on_hand - st.reserved <= p.low_stock_threshold)::bigint AS low_count,
    COUNT(*) FILTER (WHERE st.on_hand - st.reserved <= 0)::bigint AS out_count,
    COUNT(*)::bigint AS item_count
FROM stock_levels st
JOIN products p ON p.organization_id = st.organization_id AND p.id = st.product_id AND p.deleted_at IS NULL
LEFT JOIN product_variants v ON v.organization_id = st.organization_id AND v.id = st.variant_id
WHERE st.organization_id = $1
  AND ($2::bigint[] IS NULL OR st.branch_id = ANY($2::bigint[]))
  AND ($3::bigint[] IS NULL OR st.branch_id = ANY($3::bigint[]))
GROUP BY st.branch_id
ORDER BY st.branch_id
`

type ReportStockLevelsParams struct {
	OrganizationID  int64   `json:"organization_id"`
	BranchIds       []int64 `json:"branch_ids"`
	FilterBranchIds []int64 `json:"filter_branch_ids"`
}

type ReportStockLevelsRow struct {
	BranchID   int64          `json:"branch_id"`
	OnHand     int64          `json:"on_hand"`
	Reserved   int64          `json:"reserved"`
	StockValue pgtype.Numeric `json:"stock_value"`
	LowCount   int64          `json:"low_count"`
	OutCount   int64          `json:"out_count"`
	ItemCount  int64          `json:"item_count"`
}

// Stock now per branch (not bound to the period): units on hand and held,
// the value at the current unit cost, and the items that are low (at or
// below the threshold) or out (nothing free). Removed products are left
// out.
func (q *Queries) ReportStockLevels(ctx context.Context, arg ReportStockLevelsParams) ([]ReportStockLevelsRow, error) {
	rows, err := q.db.Query(ctx, reportStockLevels, arg.OrganizationID, arg.BranchIds, arg.FilterBranchIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReportStockLevelsRow{}
	for rows.Next() {
		var i ReportStockLevelsRow
		if err := rows.Scan(
			&i.BranchID,
			&i.OnHand,
			&i.Reserved,
			&i.StockValue,
			&i.LowCount,
			&i.OutCount,
			&i.ItemCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reportStockMovements = `-- name: ReportStockMovements :many
WITH mv AS (
    SELECT m.branch_id, m.kind, m.quantity,
        (m.occurred_at AT TIME ZONE COALESCE(NULLIF(b.timezone, ''), org.timezone))::date AS day
    FROM stock_movements m
    JOIN branches b ON b.organization_id = m.organization_id AND b.id = m.branch_id
    JOIN organizations org ON org.id = m.organization_id
    WHERE m.organization_id = $3
      AND m.occurred_at >= $1::date - INTERVAL '1 day'
      AND m.occurred_at < $2::date + INTERVAL '2 days'
      AND ($4::bigint[] IS NULL OR m.branch_id = ANY($4::bigint[]))
      AND ($5::bigint[] IS NULL OR m.branch_id = ANY($5::bigint[]))
)
SELECT mv.branch_id, mv.kind::text AS kind, COALESCE(SUM(mv.quantity), 0)::bigint AS quantity, COUNT(*)::bigint AS movement_count
FROM mv
WHERE mv.day BETWEEN $1::date AND $2::date
GROUP BY mv.branch_id, mv.kind
ORDER BY mv.branch_id, mv.kind
`

type ReportStockMovementsParams struct {
	DateFrom        pgtype.Date `json:"date_from"`
	DateTo          pgtype.Date `json:"date_to"`
	OrganizationID  int64       `json:"organization_id"`
	BranchIds       []int64     `json:"branch_ids"`
	FilterBranchIds []int64     `json:"filter_branch_ids"`
}

type ReportStockMovementsRow struct {
	BranchID      int64  `json:"branch_id"`
	Kind          string `json:"kind"`
	Quantity      int64  `json:"quantity"`
	MovementCount int64  `json:"movement_count"`
}

// Units moved per branch and kind in the period (local day of
// occurred_at in the branch time zone). Adjustments are signed.
func (q *Queries) ReportStockMovements(ctx context.Context, arg ReportStockMovementsParams) ([]ReportStockMovementsRow, error) {
	rows, err := q.db.Query(ctx, reportStockMovements,
		arg.DateFrom,
		arg.DateTo,
		arg.OrganizationID,
		arg.BranchIds,
		arg.FilterBranchIds,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReportStockMovementsRow{}
	for rows.Next() {
		var i ReportStockMovementsRow
		if err := rows.Scan(
			&i.BranchID,
			&i.Kind,
			&i.Quantity,
			&i.MovementCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
